r.append(R(6870063,"ब्रोकली, फ्रोज़न और पकी हुई","बिना किसी अतिरिक्त सामग्री के तैयार की गई फ्रोज़न ब्रोकली।","4","1/2 कप",
["2 कप फ्रोज़न ब्रोकली के फूल"],["पैकेट पर दिए निर्देशों के अनुसार ब्रोकली को भाप में पकाएँ, माइक्रोवेव करें या रोस्ट करें।"]))
r.append(R(6872161,"भूमध्यसागरीय स्पेल्ट फ्लैटब्रेड","यह फ्लैटब्रेड एक बढ़िया स्टार्टर भी है। इसे छोटे टुकड़ों में काटकर पार्टी के लिए शानदार नाश्ते के रूप में परोसकर देखें।","8","1 टुकड़ा",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","3/4 कप गुनगुना पानी","1 पैकेट एक्टिव ड्राई यीस्ट","1/2 छोटा चम्मच शहद","1 बड़ा अंडा","1/2 छोटा चम्मच कोशर नमक","1/4 कप स्पेल्ट का आटा (छिड़कने के लिए थोड़ा और)","1/2 कप साबुत गेहूँ का आटा","1 मध्यम पीली शिमला मिर्च (पतली कटी हुई)","1 कप ग्रेप टमाटर (आधे कटे हुए)","3 कप अरुगुला","3 औंस फ़ेटा चीज़ (कम वसा वाला)","1 1/2 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच बालसमिक सिरका","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। एक बड़ी बेकिंग शीट पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","गुनगुने पानी में यीस्ट और शहद डालें और 5 मिनट के लिए रहने दें। यीस्ट में झाग बन जाना चाहिए। इसमें अंडा और नमक फेंटकर मिलाएँ, फिर आटे डालकर गोला बना लें। आटा चिपचिपा होगा। इसे ढककर एक तरफ़ रख दें।","पीली शिमला मिर्च, ग्रेप टमाटर, अरुगुला और फ़ेटा चीज़ को जैतून के तेल, बालसमिक सिरके और काली मिर्च के साथ अच्छी तरह मिलाएँ।","हाथों पर थोड़ा और स्पेल्ट का आटा लगाएँ और आटे को बेकिंग शीट पर लगभग 9 इंच x 13 इंच या उससे बड़े आयत के रूप में फैलाएँ। आटा अपेक्षाकृत पतला होना चाहिए।","सब्ज़ियों का मिश्रण आटे पर समान रूप से डालें, किनारे के चारों ओर लगभग 1/2 इंच खाली छोड़ दें।","20 मिनट तक बेक करें, फिर 8 टुकड़ों में काट लें।"]))
r.append(R(6876203,"जिंजरस्नैप के साथ कद्दू पुडिंग परफ़ेट","बिना पकाए बनने वाली यह मिठाई कद्दू की पाई का बढ़िया विकल्प है, और इसमें सिर्फ़ 100 कैलोरी हैं! कद्दू की त्वरित, सेहतमंद और स्वादिष्ट मिठाई के लिए और कहीं देखने की ज़रूरत नहीं, यह पुडिंग परफ़ेट शानदार है और मिनटों में तैयार हो जाता है।","7","1 परफ़ेट",
["1 (1 औंस) पैकेट इंस्टेंट चीज़केक पुडिंग मिक्स (वसा रहित, शुगर-फ्री)","1 2/3 कप स्किम दूध","1 कप डिब्बाबंद शुद्ध कद्दू","1/2 छोटा चम्मच पिसी दालचीनी","1/8 छोटा चम्मच पिसा जायफल","1 कप ग्रीक वनीला दही (वसा रहित, बाँटकर इस्तेमाल करें)","7 साबुत जिंजरस्नैप कुकीज़ (चूरा की हुई)"],
["एक मध्यम मिक्सिंग बाउल में पुडिंग मिक्स और दूध को 2 मिनट तक फेंटें। 5 मिनट के लिए रहने दें।","कद्दू, दालचीनी और जायफल को धीरे से मिलाएँ। इसमें 1/2 कप दही मिलाएँ और 10 मिनट के लिए फ्रिज में रखें।","हर परफ़ेट ग्लास में 1/2 कप पुडिंग का मिश्रण डालें। हर एक के ऊपर बचे हुए दही का 1 ढेर लगा बड़ा चम्मच और 1 चूरा की हुई जिंजरस्नैप कुकी डालें। बाकी 6 परफ़ेट के लिए यही प्रक्रिया दोहराएँ।"]))
r.append(R(6876375,"मोहितो स्वीटी मैश","पुदीने और नीबू के रस से इन मसले हुए शकरकंद को मोहितो जैसा स्वाद मिलता है! संपूर्ण, संतुलित भोजन के लिए इसे किसी सरल प्रोटीन के साथ परोसें और अपनी प्लेट का बाकी हिस्सा बिना स्टार्च वाली सब्ज़ी से भरें।","4","लगभग 1/2 कप",
["2 बड़े शकरकंद (बिना छिले, लगभग 1 1/2 पाउंड)","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच ताज़ा पुदीना (कटा हुआ)","2 बड़े चम्मच नीबू का रस","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["साबुत शकरकंद को एक बड़े सॉसपैन में रखें और उन्हें डुबाने लायक ठंडा पानी डालें। तेज़ आँच पर शकरकंद को उबालें। आँच को मध्यम-धीमी करें और नरम होने तक 30-35 मिनट धीमी आँच पर पकाएँ। शकरकंद का पानी निकाल दें और ठंडे पानी से तब तक धोएँ जब तक उन्हें पकड़ना आसान न हो जाए।","इस बीच, एक छोटे सॉसपैन में तेल को तेज़ आँच पर लगभग 1 मिनट तक गुनगुना होने तक गरम करें। (या तेल को माइक्रोवेव-सुरक्षित कटोरे में तेज़ आँच पर लगभग 30 सेकंड तक गुनगुना होने तक गरम करें।) पुदीने की पत्तियाँ डालें और लकड़ी के चम्मच के हैंडल या मूसल से कुचल दें। एक तरफ़ रख दें।","शकरकंद छीलें और उन्हें वापस सॉसपैन में रखें। पुदीने का मिश्रण, नीबू का रस, नमक और काली मिर्च डालें। आलू मैशर से शकरकंद को चिकना और मलाईदार होने तक मसलें। शकरकंद को परोसने के कटोरे में निकालें, पुदीने की टहनियों से सजाएँ और गरमागरम परोसें।"]))
r.append(R(6877039,"प्रोवेंसल शैली में जड़ी-बूटियों के साथ रोस्ट की हुई टर्की ब्रेस्ट","यह व्यंजन एमी रिओलो के अमेरिकी थैंक्सगिविंग भोजन का सबसे खास आकर्षण बन गया है। जड़ी-बूटियों, लहसुन, मसालों और नीबू के रस का मेल स्वादिष्ट और रसदार टर्की बनाता है, जिसे तैयार करना आसान है। टर्की को प्रति पाउंड 20-25 मिनट के हिसाब से रोस्ट करना चाहिए।","10","3 औंस",
["1/4 कप एक्स्ट्रा वर्जिन जैतून का तेल (बाँटकर)","3 1/2 पाउंड हड्डी वाली टर्की ब्रेस्ट","1/2 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च (ताज़ा पिसी, स्वादानुसार)","1 बड़ा चम्मच हर्ब्स डी प्रोवेंस","1 छोटा चम्मच पोल्ट्री सीज़निंग","लहसुन का 1 गुच्छा (ऊपर का हिस्सा कटा हुआ)","2 मध्यम नीबू (आधे कटे हुए)","1 टहनी ताज़ा रोज़मेरी","1 टहनी ताज़ा थाइम","1 टहनी ताज़ा सेज"],
["ओवन को 425°F पर पहले से गरम करें। एक बड़े रोस्टिंग पैन की तली पर चिकनाई लगाने के लिए 1 बड़ा चम्मच जैतून का तेल इस्तेमाल करें।","टर्की ब्रेस्ट को पेपर टॉवल से थपथपाकर सुखा लें और नमक व काली मिर्च लगाएँ। टर्की ब्रेस्ट को त्वचा वाली तरफ़ ऊपर करके पैन में रखें। टर्की पर बचा हुआ जैतून का तेल लगाएँ। टर्की पर हर्ब्स डी प्रोवेंस और पोल्ट्री सीज़निंग छिड़कें और हाथों से त्वचा पर मल दें। पैन में लहसुन का साबुत गुच्छा, 1 नीबू का आधा हिस्सा, रोज़मेरी, थाइम और सेज रखें। बचे हुए नीबू के आधे हिस्से का रस टर्की के ऊपर निचोड़ें।","टर्की को ओवन में रखें, पैन की तली में 1 कप पानी डालें और बिना ढके 1 घंटे तक रोस्ट करें। पहले घंटे के बाद टर्की पर पैन का रस चम्मच से डालें। अगर टर्की बहुत भूरी दिखे, तो उसे फ़ॉइल से ढक दें। 30-45 मिनट और बेक करते रहें, जब तक कि मीट थर्मामीटर पर टर्की ब्रेस्ट के सबसे मोटे हिस्से का आंतरिक तापमान 180°F न हो जाए। ओवन से निकालें और कटिंग बोर्ड पर रखें। काटने से पहले 10 मिनट रहने दें। काटते समय त्वचा हटा दें।","पैन की तली का तरल पदार्थ छानकर दूसरे सॉसपैन में डालें। बचे हुए 2 नीबू के आधे हिस्सों का रस निकालकर सॉसपैन में डालें और चलाएँ। तेज़ आँच पर उबाल लाएँ और 10 मिनट तक या सॉस के गाढ़ा होने तक पकाएँ। चखकर, ज़रूरत हो तो मसाले ठीक करें। सॉस को ग्रेवी बोट में टर्की के पास परोसें।"]))
r.append(R(6877159,"सब्ज़ियों और चिकन वाला पास्ता सलाद","अपने भोजन योजना में पास्ता शामिल करने और कार्बोहाइड्रेट ज़्यादा न होने देने की कुंजी है पास्ता की मात्रा कम रखना और उसे ढेर सारी सब्ज़ियों और थोड़े प्रोटीन के साथ परोसना। यह एक त्वरित रात का खाना है जिसका आनंद पूरा परिवार साल के किसी भी समय ले सकता है। अतिरिक्त प्रोटीन और फ़ाइबर के लिए इसे दाल या चने के पास्ता जैसे बीन-आधारित पास्ता के साथ आज़माएँ।","4","1 कप",
["1 कप बिना पका साबुत गेहूँ का एल्बो पास्ता","1/2 कप कटी हुई लाल शिमला मिर्च","1/2 कप कटा हुआ खीरा","1/2 कप छोटे ब्रोकली के फूल (ताज़ा या फ्रोज़न)","1 बड़ी गाजर (कटी हुई)","1 कप कटा हुआ पका चिकन ब्रेस्ट","1/4 कप लाइट मेयोनेज़","1 बड़ा चम्मच रेड वाइन सिरका","1/8 छोटा चम्मच सूखा अजवायन","1/8 छोटा चम्मच ताज़ी पिसी काली मिर्च"],
["पैकेट पर दिए निर्देशों के अनुसार पास्ता पकाएँ। पानी निकाल दें।","एक बड़े कटोरे में पास्ता, लाल शिमला मिर्च, खीरा, ब्रोकली, गाजर और चिकन को मिलाएँ।","एक छोटे कटोरे में ड्रेसिंग की सामग्री को फेंटकर मिलाएँ। ड्रेसिंग को पास्ता, सब्ज़ियों और चिकन पर डालें और अच्छी तरह मिलाएँ। परोसें।"]))
r.append(R(6878911,"पीनट बटर केला ओट बाइट्स","ये पेट भरने वाले, उच्च फ़ाइबर युक्त बाइट्स बढ़िया स्नैक या त्वरित नाश्ता बनते हैं। आप कुछ बाइट्स को स्नैक-साइज़ प्लास्टिक बैग में फ्रीज़ करके चलते-फिरते नाश्ते के लिए भी रख सकते हैं!","24","2 बाइट्स",
["1 बड़ा अंडा","1 मध्यम केला (मसला हुआ)","1/2 कप पीनट बटर (माइक्रोवेव में 30 सेकंड के लिए गरम किया हुआ)","1 छोटा चम्मच वनीला एक्सट्रैक्ट","2 बड़े चम्मच कम कैलोरी वाला ब्राउन शुगर विकल्प","2 कप पुराने ज़माने के रोल्ड ओट्स (ज़रूरत हो तो ग्लूटेन-फ्री)","1 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच नमक","1/4 कप पिसे हुए अलसी के बीज"],
["ओवन को 350°F पर पहले से गरम करें। बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","एक मध्यम कटोरे में पीनट बटर, केला, अंडा, वनीला और ब्राउन शुगर विकल्प को फेंटकर मिलाएँ।","एक छोटे कटोरे में ओट्स, बेकिंग सोडा और नमक मिलाएँ। इसमें पिसे हुए अलसी के बीज डालें।","ओट्स के मिश्रण को पीनट बटर के मिश्रण में डालें और अच्छी तरह मिलाएँ।","घोल को 1 बड़े चम्मच के गोलों में निकालकर बेकिंग शीट पर रखें। 10-12 मिनट तक बेक करें। वायर रैक पर ठंडा करें।"]))
r.append(R(6881554,"टर्की मीटबॉल्स और ज़ुकीनी नूडल्स","इस इतालवी शैली के व्यंजन में स्वादिष्ट टर्की मीटबॉल्स और कम कार्बोहाइड्रेट वाले ज़ुकीनी नूडल्स हैं, जो एक सेहतमंद भोजन है जिसका आनंद पूरा परिवार लेगा।","4","रेसिपी का 1/4 हिस्सा",
["1 पाउंड कम वसा वाली कीमा टर्की (93% कम वसा)","1/2 कप ब्रेड क्रम्ब्स","1/4 कप पारमेसन चीज़ (कसा हुआ)","1 बड़ा अंडा","2 फाँक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच सूखा अजवायन","1/2 छोटा चम्मच काली मिर्च (बाँटकर)","2 कप मरीनारा सॉस (बिना नमक मिलाए)","4 मध्यम ज़ुकीनी (स्पाइरलाइज़ करके नूडल्स बनाई हुई)","1/4 कप कलामाता ज़ैतून (गुठली निकले हुए)","1 1/2 बड़े चम्मच जैतून का तेल","1 बड़ा चम्मच ताज़ा अजमोदा (कटा हुआ)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। दो शीट पैन पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","एक मिक्सिंग बाउल में कीमा टर्की, ब्रेड क्रम्ब्स, पारमेसन चीज़, अंडा, बारीक कटा लहसुन, सूखा अजवायन और 1/4 छोटा चम्मच काली मिर्च मिलाएँ। अच्छी तरह मिलने तक मिलाएँ।","गीले हाथों से मिश्रण के लगभग 1 इंच व्यास के मीटबॉल्स बनाएँ और उन्हें शीट पैन पर रखें। 20 मिनट तक या आंतरिक तापमान 165 डिग्री F होने तक बेक करें।","जब मीटबॉल्स बेक हो रहे हों, तब ज़ुकीनी नूडल्स को जैतून के तेल और 1/4 छोटा चम्मच काली मिर्च के साथ मिलाएँ और उन्हें दूसरे शीट पैन पर फैला दें।","नरम होने तक, लगभग 10-15 मिनट बेक करें।","मरीनारा सॉस को चूल्हे पर गरम करें और गरमागरम मीटबॉल्स को सॉस में लपेट लें।","मीटबॉल्स को ज़ुकीनी नूडल्स के ऊपर परोसें और ज़ैतून और ताज़े अजमोदा से सजाएँ।"]))
r.append(R(6882153,"करी डेविल्ड एग्स","करी डेविल्ड एग्स एक शानदार स्टार्टर हैं जो आपकी मेज़ पर मसाले और गरमाहट का स्पर्श लाते हैं। करी पाउडर, डिजॉन सरसों और सेब के सिरके का मेल एक स्वादिष्ट और सुगंधित भरावन बनाता है, जो पार्टियों और मेल-मिलाप में ज़रूर पसंद किया जाएगा। इन अनोखे मसालेदार डेविल्ड एग्स का आनंद लें!","8","2 आधे हिस्से",
["8 बड़े अंडे","1/4 कप लाइट मेयोनेज़","1 छोटा चम्मच करी पाउडर","1 छोटा चम्मच डिजॉन सरसों","1 छोटा चम्मच सेब का सिरका","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच स्मोक्ड पेपरिका (सजाने के लिए)","1 छोटा चम्मच ताज़ा सोआ (सजाने के लिए)"],
["अंडों को सॉसपैन में एक परत में रखें और पानी से ढक दें। पानी को उबालें, फिर आँच धीमी करें, ढक दें और 10-12 मिनट तक धीमी आँच पर पकाएँ।","उबले अंडों को ठंडा करने के लिए बर्फ़ के पानी में डालें।","अंडे ठंडे हो जाएँ, तो उन्हें छीलें और लंबाई में आधा काट लें। ज़र्दी निकालकर कटोरे में रखें।","ज़र्दी वाले कटोरे में मेयोनेज़, करी पाउडर, डिजॉन सरसों, सेब का सिरका, नमक और काली मिर्च डालें। सामग्री को चिकना होने तक मसलकर मिलाएँ। करी का भरावन चम्मच से या पाइप करके अंडे की खोखली सफ़ेदी में भरें।","परोसने से पहले कम से कम 30 मिनट फ्रिज में ठंडा करें। ऊपर से हल्का सा पेपरिका छिड़कें और चाहें तो ताज़ा सोआ डालें।"]))
r.append(R(6884440,"क्रीमी सेलेरी क्रंच बाइट्स","ये ताज़गी देने वाले स्नैक बाइट्स कुरकुरी सेलेरी को चिकने वसा रहित क्रीम चीज़ और कद्दू व सूरजमुखी के बीजों की छिड़कन के साथ मिलाते हैं, जिससे कुरकुरेपन और मलाईदारपन का संतोषजनक मेल बनता है। ये मिनटों में बन जाते हैं और एक हल्का, ऊर्जा देने वाला एकल-सर्विंग स्नैक बनते हैं।","1","भरी हुई 4 सेलेरी डंडियाँ",
["4 सेलेरी की डंडियाँ","4 बड़े चम्मच वसा रहित क्रीम चीज़","2 बड़े चम्मच कद्दू के बीज (बिना नमक के)","2 बड़े चम्मच सूरजमुखी के बीज (बिना नमक के)"],
["4 सेलेरी की डंडियों को धोएँ और किनारे काट लें।","4 बड़े चम्मच वसा रहित क्रीम चीज़ को सेलेरी की नालियों में समान रूप से फैलाएँ।","हर सेलेरी की डंडी के लिए क्रीम चीज़ के ऊपर 1/2 बड़ा चम्मच कद्दू के बीज और 1/2 बड़ा चम्मच सूरजमुखी के बीज छिड़कें।","सबसे अच्छे कुरकुरेपन के लिए तुरंत परोसें।"]))
r.append(R(6885965,"बैंगन और छोले का स्ट्यू","इस स्वादिष्ट शाकाहारी मुख्य व्यंजन को इसका अनोखा स्वाद लहसुन, प्याज़ और मसालों के मेल से मिलता है। ये आपको कम नमक डाले बिना ज़्यादा से ज़्यादा स्वाद पाने में मदद करते हैं।","4","1 1/2 कप",
["4 छोटे चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (बाँटकर)","2 मध्यम पीले प्याज़ (1 कटा हुआ और 1 लंबा कटा हुआ)","3 फाँक लहसुन (बारीक कटा हुआ)","1 पाउंड बैंगन (टुकड़ों में कटा हुआ)","2 कप छोले (काबुली चना) (बिना नमक मिलाए)","1 छोटा चम्मच जीरा","1 छोटा चम्मच पिसी दालचीनी","1 छोटा चम्मच पिसा धनिया","28 औंस डिब्बाबंद टमाटर (बिना नमक मिलाए, कटे हुए)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप हरा धनिया (ताज़ा कटा हुआ)"],
["एक बड़े सॉसपैन में 2 छोटे चम्मच जैतून का तेल मध्यम आँच पर गरम करें।","कटे हुए प्याज़ और लहसुन डालें और प्याज़ के नरम होने तक पकाएँ।","बैंगन, छोले, जीरा, दालचीनी, धनिया, टमाटर, नमक और काली मिर्च डालकर चलाएँ। आँच तेज़ करें और उबाल आने दें।","आँच धीमी करें और बरतन को ढक दें। स्ट्यू को 45 मिनट से 1 घंटे तक या बैंगन के बहुत नरम होने तक पकाएँ।","इस बीच, बचे हुए 2 छोटे चम्मच जैतून के तेल को गरम करें और प्याज़ के लंबे टुकड़े डालें। सुनहरा होने तक तलें और आँच से हटा लें।","स्ट्यू तैयार होने पर उसे परोसने के कटोरों में निकालें और ऊपर से तले हुए प्याज़ और हरा धनिया डालें।"]))
r.append(R(6886065,"चिकन शावरमा कोलार्ड रैप्स","ये चिकन शावरमा कोलार्ड रैप्स तेज़ मसालों और ताज़ी सब्ज़ियों से भरपूर हैं, जो पारंपरिक फ्लैटब्रेड की जगह मज़बूत, कम कार्बोहाइड्रेट वाली कोलार्ड ग्रीन्स में लिपटे हैं। दही-ताहिनी सॉस अतिरिक्त वसा के बिना मलाईदार स्वाद देती है। उच्च प्रोटीन और फ़ाइबर वाले और बिना परिष्कृत अनाज के ये रैप्स स्वादिष्ट और मधुमेह के अनुकूल हैं।","4","2 रैप्स",
["1 पाउंड बिना हड्डी और बिना त्वचा वाली चिकन जाँघें","2 बड़े चम्मच जैतून का तेल","3 फाँक लहसुन (बारीक कटा हुआ, बाँटकर इस्तेमाल करें)","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच पिसा धनिया","1/2 छोटा चम्मच हल्दी","1/4 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच लाल मिर्च पाउडर (वैकल्पिक)","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","3 बड़े चम्मच नीबू का रस (1 1/2 मध्यम नीबू से, बाँटकर इस्तेमाल करें)","8 कोलार्ड ग्रीन्स के पत्ते (बड़े पत्ते, डंठल कटे हुए)","1/2 कप सादा वसा रहित ग्रीक दही","1 बड़ा चम्मच ताहिनी","1 कप खीरा (माचिस की तीलियों जैसे पतले टुकड़ों में कटा हुआ)","1 कप चेरी टमाटर (आधे कटे हुए)","1/4 छोटा लाल प्याज़"],
["एक बड़े कटोरे में जैतून का तेल, लहसुन, जीरा, पेपरिका, धनिया, हल्दी, दालचीनी, लाल मिर्च पाउडर (अगर इस्तेमाल कर रहे हों), नमक, काली मिर्च और 1 बड़ा चम्मच नीबू का रस मिलाएँ। चिकन की जाँघें डालें और समान रूप से लपेटें। फ्रिज में कम से कम 30 मिनट या रातभर तक मैरिनेट करें।","ग्रिल पैन या कड़ाही को मध्यम आँच पर पहले से गरम करें। चिकन की जाँघों को हर तरफ़ 5-7 मिनट या पूरी तरह पकने तक पकाएँ। 5 मिनट रहने दें, फिर पतले टुकड़ों में काट लें।","एक बड़े बरतन में पानी उबालें। कोलार्ड के हर पत्ते को एक-एक करके 30-45 सेकंड तक ब्लैंच करें, जब तक कि वह चटक हरा और लचीला न हो जाए। उसे बर्फ़ के पानी में डालें, फिर थपथपाकर सुखा लें।","एक छोटे कटोरे में दही, ताहिनी, 1 बड़ा चम्मच नीबू का रस और 2 फाँक बारीक कटा लहसुन डालें। चिकना होने तक फेंटें।","अब रैप्स बनाने के लिए तैयार हैं। कोलार्ड का एक पत्ता समतल बिछाएँ। उस पर एक चम्मच दही-ताहिनी सॉस (1/2 कप सादा वसा रहित ग्रीक दही; 1 बड़ा चम्मच ताहिनी; 1 बड़ा चम्मच नीबू का रस; और 1 छोटी फाँक बारीक कटा लहसुन) फैलाएँ। ऊपर कटा हुआ चिकन, खीरा, चेरी टमाटर और लाल प्याज़ रखें। किनारों को मोड़ें और बरिटो की तरह लपेटें।","चाहें तो हर रैप को आधा काट लें और तुरंत परोसें। बचे हुए रैप्स को कसकर लपेटकर फ्रिज में 2 दिन तक रखा जा सकता है।"]))
r.append(R(6886220,"सुपर फ़ूड्स सलाद","यह सलाद न सिर्फ़ बेहद पौष्टिक लगता है, बल्कि स्वाद से भी भरपूर है। 4 छोटे चम्मच सूखी क्रैनबेरी, 1/4 कप अनार के दाने या एक कटा हुआ संतरा डालकर स्वाद और बढ़ाएँ। या हरी पत्तियों के लिए बेबी अरुगुला चुनें। संपूर्ण भोजन के लिए रोस्टेड चिकन या पोर्क के साथ परोसें।","6","1 1/2 कप",
["1/2 कप क्विनोआ","6 औंस ताज़ा छिले हुए एडामामे ((1 कप))","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1 बड़ा चम्मच नीबू का रस (ताज़ा)","1 बड़ा चम्मच संतरे का रस (बेहतर हो ताज़ा)","1/4 साबुत एवोकाडो","2 बड़े चम्मच ताज़ा हरा धनिया या अजमोदा (मोटा कटा हुआ)","1/2 छोटा चम्मच कोशर नमक","1 फाँक लहसुन (छिला और आधा कटा हुआ)","1 सलाद पत्ता (लगभग 6 औंस, ज़रूरत हो तो कटा या हाथ से फाड़ा हुआ)","1/2 मध्यम नारंगी शिमला मिर्च (बीज निकालकर कटी हुई)","2 बड़े चम्मच बिना नमक के सूरजमुखी के बीज, या पेकान या पिस्ता इस्तेमाल करें"],
["क्विनोआ को धोकर 1 कप पानी में लगभग 10 मिनट या पानी सूखने तक पकाएँ। उसे कांटे से फुलाएँ और आँच से हटा लें।","इस बीच, एडामामे को लगभग 4 कप उबलते पानी में 5 मिनट तक पकाएँ।","एक छोटे फ़ूड प्रोसेसर या ब्लेंडर में तेल, नीबू और संतरे का रस, एवोकाडो, हरा धनिया, नमक और लहसुन को प्यूरी कर लें।","एक बड़े सलाद बाउल में सलाद पत्ता, शिमला मिर्च, क्विनोआ, एडामामे और सूरजमुखी के बीज मिलाएँ। ड्रेसिंग सब पर डालें और धीरे से मिलाएँ। तुरंत परोसें।","पहले से तैयारी करें या किसी को सौंपें: क्विनोआ और एडामामे पकाएँ, संतरे का रस निकालें, हरा धनिया काटें, लहसुन छीलें, ड्रेसिंग तैयार करें और शिमला मिर्च काटें।"]))
r.append(R(6886675,"रोस्टेड पत्तागोभी स्टेक्स","पत्तागोभी किफ़ायती और बहुमुखी सब्ज़ी है। इस रेसिपी में पत्तागोभी के पूरे गोले को मोटे \"स्टेक्स\" में काटकर रोस्ट किया जाता है, जो भरपेट साइड डिश या शाकाहारी मुख्य व्यंजन बनता है। इन्हें ग्रिल पर पकाना भी बढ़िया रहेगा। स्टेक्स के ऊपर डालने के लिए आप ग्रीक दही और सोआ की सरल सॉस बना सकते हैं।","6","1 पत्तागोभी स्टेक",
["1 हरी पत्तागोभी का गोला","2 बड़े चम्मच जैतून का तेल","1/2 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच बिना नमक वाला सर्व-उपयोगी मसाला मिश्रण, जैसे Mrs. Dash®","1 बड़ा चम्मच ताज़ा सोआ (कटा हुआ)"],
["ओवन को 350° F पर पहले से गरम करें। पत्तागोभी के गोले को 1\" मोटे छह टुकड़ों में काटें।","पत्तागोभी के टुकड़ों को बेकिंग शीट पर रखें और ऊपर से जैतून का तेल डालें। पत्तागोभी पर मसाला मिश्रण और सोआ छिड़कें। एल्यूमीनियम फ़ॉइल से ढक दें।","45 मिनट तक बेक करें। फ़ॉइल हटाएँ और पत्तागोभी के स्टेक्स को ओवन में 15 मिनट और भूरा होने दें।"]))
r.append(R(6886722,"पेस्टो भरा चिकन ब्रेस्ट और ब्रुशेटा सॉस","कम कार्बोहाइड्रेट वाली यह भरवाँ चिकन रेसिपी मधुमेह प्लेट पद्धति वाले भोजन का आदर्श केंद्रबिंदु है। साबुत अनाज के पास्ता या क्विनोआ की छोटी मात्रा और साइड सलाद के साथ परोसा गया यह आकर्षक व्यंजन प्रभावित करने के लिए बनाया गया है। शेफ़ की सलाह: इस रेसिपी में चिकन ब्रेस्ट को बटरफ़्लाई करना होता है। अगर आप इस तकनीक से परिचित नहीं हैं, तो चिंता न करें! यह एक सरल तरीका है जिससे चिकन में भरावन भरना या ब्रेस्ट को बिना सुखाए जल्दी पकाना आसान हो जाता है।","6","4 औंस चिकन",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","3 मध्यम रोमा (प्लम) टमाटर (बीज निकालकर कटे हुए)","1/2 छोटा लाल प्याज़ (छोटे टुकड़ों में कटा हुआ)","1 बड़ा चम्मच ताज़ा अजवायन (कटी हुई)","1 बड़ा चम्मच रेड वाइन सिरका","1 बड़ा चम्मच जैतून का तेल","2 1/4 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च","1/4 कप ताज़ी तुलसी (कटी हुई)","1/4 कप पारमेसन चीज़ (ताज़ा कसा हुआ)"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। बेकिंग डिश पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","एक छोटे कटोरे में टमाटर, लाल प्याज़, अजवायन, रेड वाइन सिरका और जैतून का तेल मिलाएँ।","हर चिकन ब्रेस्ट को बटरफ़्लाई करें और हर एक को किताब की तरह खोलें। सभी चिकन ब्रेस्ट के दोनों तरफ़ नमक और काली मिर्च लगाएँ।","एक छोटे कटोरे में तुलसी और पारमेसन चीज़ को मिलाएँ और फिर इस मिश्रण को हर खुले चिकन ब्रेस्ट में बराबर बाँट दें। चिकन ब्रेस्ट को वापस आधा मोड़ें और बेकिंग पैन में रखें।","टमाटर का मिश्रण चिकन ब्रेस्ट के ऊपर डालें और 35-45 मिनट (चिकन ब्रेस्ट के आकार के अनुसार) या आंतरिक तापमान 165 डिग्री F होने तक बेक करें।"]))
save(1,r)
